import React from 'react';
import { Tree } from '@alifd/next';

const data = [{
    key: '0-0',
    label: '0-0',
    children: [{
        key: '0-0-0',
        label: '0-0-0',
        children: [{
            key: '0-0-0-0',
            label: '0-0-0-0'
        }]
    }]
}];

class Demo extends React.Component {
    constructor(props) {
        super(props);
        this.state = {
            selectedKeys: []
        };
        this.handleSelect = this.handleSelect.bind(this);
    }

    handleSelect(keys, info) {
        console.log('Selected keys:', keys, 'Extra:', info.extra);
        this.setState({
            selectedKeys: keys
        });
    }

    render() {
        return (
            <Tree
                selectable
                selectedKeys={this.state.selectedKeys}
                onSelect={this.handleSelect}
                dataSource={data}
            />
        );
    }
}

ReactDOM.render(<Demo />, mountNode);
